// TCPA's federal floor: 8am-9pm in the called party's own local time. State overrides narrow
// that window further where a state sets a tighter one - flagged for counsel confirmation before
// launch, same treatment as every other legally-consequential default in this repo
// (CRM-OBJECT-MODEL.md's Compliance layer section). Empty on purpose: no state override is
// encoded here without a verified source, rather than guess at one.
const STATE_HOUR_OVERRIDES = {};
const FEDERAL_START_HOUR = 8;
const FEDERAL_END_HOUR = 21;

const location = $('Fetch Location').item.json;
const webhookBody = $('Compliant hours webhook').item.json.body;
const requestedAt = webhookBody.requestedAt ? new Date(webhookBody.requestedAt) : new Date();

const [startHour, endHour] = STATE_HOUR_OVERRIDES[location.state] || [FEDERAL_START_HOUR, FEDERAL_END_HOUR];

// KNOWN LIMITATION, flagged rather than silently wrong: this reads the SERVER's local hour, not
// the called party's actual local time zone. Location only has a US state (added this pass), not
// a timezone/UTC offset, and several states span multiple zones or have partial DST exceptions
// (AZ, IN). A real implementation needs a state/zip -> timezone lookup (or Location's own
// timezone field) before this is trustworthy in production - this is the honest placeholder
// until that exists, not a solved calculation.
const localHour = requestedAt.getHours();
const inWindow = localHour >= startHour && localHour < endHour;

return [{
  json: {
    inWindow,
    localHour,
    windowStart: startHour,
    windowEnd: endHour,
    reason: inWindow
      ? `Within the ${startHour}:00-${endHour}:00 compliant-hours window for state ${location.state || 'unknown'}.`
      : `Outside the ${startHour}:00-${endHour}:00 compliant-hours window for state ${location.state || 'unknown'} - needs a system-checked and human-verified off-hours ConsentRecord.`,
  },
}];

function asArray(item) {
  const json = item.json;
  if (Array.isArray(json)) return json;
  if (json && json.data && Array.isArray(json.data.consentRecords)) return json.data.consentRecords;
  if (json && Array.isArray(json.consentRecords)) return json.consentRecords;
  return [];
}

const records = $input.all().flatMap(asArray);

// Dual gate, fails closed on either half missing (CRM-OBJECT-MODEL.md's ConsentRecord section,
// per Jonathan's explicit 'system checks existence, human confirms validity' answer): evidenceRef
// existing is necessary but not sufficient - a human still has to have verified it.
const verified = records.find((r) => r.evidenceRef && r.verifiedByRepId && r.verifiedAt);

if (verified) {
  return [{
    json: {
      consentVerified: true,
      consentRecordId: verified.id,
      reason: 'A verified off-hours ConsentRecord is on file.',
    },
  }];
}

const hasUnverifiedEvidence = records.some((r) => r.evidenceRef);
return [{
  json: {
    consentVerified: false,
    reason: hasUnverifiedEvidence
      ? 'A ConsentRecord with evidence exists but has not been human-verified yet - blocked until verifiedByRepId/verifiedAt are set.'
      : 'No off-hours ConsentRecord with evidence (recording ID, email, or SMS message ID) on file for this Opportunity.',
  },
}];
